"""Human translations of complete biography fields, preserving inline markup."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / 'localization/stories'
cat = json.loads((BASE/'catalogue.json').read_text(encoding='utf-8'))
translations = {
16: '<p>贝拉克·奥巴马在2008年大选中击败约翰·麦凯恩，如今以现任总统身份参加2012年竞选。他以温和自由派路线执政，推动通过了医疗改革方案，并在部分外交问题上采取鹰派立场。</p><p>严重的经济衰退和乏力的复苏一直困扰着奥巴马政府。他始终将其归咎于共和党前任总统的政策，以及国会政治对手的阻挠。</p>',
17: '<p>米特·罗姆尼以共和党挑战者身份参加2012年竞选。他曾任马萨诸塞州州长，有公共服务经历，也曾领导贝恩资本多年。人们通常将他视为亲商的温和派和称职的管理者。</p><p>罗姆尼多年来在医疗和社会议题上的立场不断变化，一些保守派因此怀疑他的诚意。他面临的挑战是，既赢得这一派别的支持，又不疏远主流选民。',
36: '<p>替代历史剧本</p><p>未能获得共和党提名后，罗恩·保罗决定独立参选。虽然赢得本届大选十分困难，但他希望扩大自己的政治网络，证明类似路线的候选人在2016年也有参选的可行性。他的支持者则有了迄今最大的舞台，可以向美国公众阐述保罗最为重视的财政与宪法问题。</p>',
18: '<p>加里·约翰逊的自由意志主义立场使他在2012年缺乏竞争力，但他希望以这次选举为跳板，推广自己的政党和理念。罗恩·保罗在共和党初选中的成绩，表明约翰逊的观点有潜在受众。不过，现实地说，能拿到超过2%的普选票，他就已经很幸运了。</p>',
19: '<p>斯坦很可能只是2012年大选中的一个注脚。不过，如果奥巴马过于向政治中间地带靠拢，她就可能分走他的部分支持。</p>',
27: '<p>替代历史剧本</p><p>纽特·金里奇在共和党提名战中爆冷胜出，带着财政保守派和社会保守派的强力支持进入大选。他最为人熟知的是20世纪90年代领导众议院的经历，如今必须设法重获民众支持和政治影响力，并让美国选民相信，他比奥巴马更能解决他们关心的经济问题。</p>',
29: '<p>替代历史剧本</p><p>里克·桑托勒姆在共和党提名战中爆冷胜出，带着社会保守派的坚定支持进入大选。他也有多年担任联邦参议员的经验。</p><p>桑托勒姆击败了共和党商界派别属意的候选人，接下来必须重新团结这一派别，同时拿出能吸引广大选民中摇摆选民的主张。</p>',
30: '<p>副总统 </p>',
31: '<p>副总统</p>',
23: '<p>这位1960年大选的败选者，一度被认为政治生涯已经终结，如今却重返全国舞台，将自己包装为“新尼克松”。</p><p>尼克松将着重强调“法律与秩序”，以及结束越南战争。他希望争取足够的主流支持，在汉弗莱的自由主义与华莱士的极端主义之间走出一条中间道路。</p>',
24: '<p>多年来，汉弗莱一直被视为约翰逊理所当然的接班人。这一身份在激烈的提名争夺中既帮助了他，也拖累了他。</p><p>汉弗莱必须多线作战：为自由派理想提出清晰有力的论证，重新争取党内积极行动派，遏制华莱士的攻势，同时完成首要任务——击败令人厌恶的尼克松。</p>',
25: '<p>乔治·华莱士参选只有一个目标——阻止任何人在选举人团中取得多数，然后利用自己左右胜负的地位，迫使各方接受终止废除种族隔离的政策。</p><p>哪怕只是接近实现这一目标，他也会坐实自己作为美国政治史上重大反面人物之一的名声——或者，成为某些狭小圈子中的真正英雄。</p><p>华莱士将尽可能赢下更多南方州，以增加选举陷入僵局的机会。</p>',
20: '<p>威廉·麦金莱代表稳定和既有秩序。他以共和党人、南北战争老兵、保护关税拥护者，以及美国工业和金本位制支持者的身份参选。</p><p>金融精英几乎一致支持麦金莱。他在竞选资金上占据巨大优势，在东北部和中西部北部也拥有忠实的支持者，其中包括他的家乡俄亥俄州。</p>',
21: '<p>威廉·詹宁斯·布赖恩凭借著名的“黄金十字架”演说，震撼了芝加哥的党代会。</p><p>他以自由派和福音派基督徒的身份参选，核心主张是通过自由铸造银币扩大货币供应、推动物价上涨。这为他赢得了南方和西部农民的狂热支持。由于缺乏开展大规模竞选的资金，布赖恩将周游美国，发挥自己的演说才能。</p>',
22: '<p>支持金本位制的民主党人另推约翰·帕尔默参选。他几乎不可能赢得大选，却很可能分走布赖恩足够多的选票，使其在某些州落败。这正是保守派民主党人的目标：他们只想撑到1900年，再提名一位比激进的布赖恩更合心意的候选人。</p>',
67: '<p>亚伯拉罕·林肯以有利形势开始竞选。新成立的共和党基本团结一致，他在若干北方州拥有压倒性优势。挑战在于赢下伊利诺伊、纽约和俄亥俄等竞争较为接近的州。为此，他必须巧妙应对当时数个敏感问题，其中尤以奴隶制为甚。</p><p>共和党主张的关税、宅地政策和横贯大陆铁路等议题，同样是讨论的重点。</p>',
68: '<p>民主党的分裂使斯蒂芬·道格拉斯几乎不可能直接赢得大选。他的胜选路径是让选举交由众议院裁决，同时在选举人票数上跻身前三。这样，他便可能胜出，或者至少阻止共和党获胜。</p><p>道格拉斯一直主张“人民主权原则”，但这一折中方案在南北双方都已失去吸引力。若要阻止林肯取得多数，他必须赢下一些北方州。</p>',
69: '<p>南方民主党人不接受斯蒂芬·道格拉斯的提名，另推约翰·C.·布雷肯里奇参选。与道格拉斯一样，布雷肯里奇直接赢得大选的机会很小，但他很有希望拿下全部或大多数南方州。</p><p>作为狂热支持奴隶制的候选人，也就是所谓的“食火者”，布雷肯里奇必须捍卫<em>德雷德·斯科特</em>案判决，并在选举人团陷入僵局后的众议院谈判中，代表蓄奴利益。</p>',
70: '<p>约翰·贝尔曾是辉格党人。尽管自己也是奴隶主，他却没有公开表明对奴隶制的立场。他唯一的主张是在任何情况下都维护联邦。这种模糊态度既是优势，也是负担。</p><p>贝尔的根基在边界州。若林肯未能在选举人团中获胜，他希望在谈判桌上占有一席之地，促成妥协，阻止任何南方州脱离联邦。</p>',
77: '<p>乔治·W.·布什进入2000年竞选时，既有共和党建制派的支持，也有父亲带来的知名度。他已治理得克萨斯州五年，赢得了该州两党的支持，如今希望将同样的做法带到全国。</p><p>布什具有广泛的吸引力，支持阵营也很团结，但一些人认为他经验不足，缺乏领袖应有的分量。他能否让选民相信，自己能够超越克林顿时代的党争，将“富有同情心的保守主义”带给全国？</p>',
78: '<p>阿尔·戈尔在比尔·克林顿政府中担任副总统八年后，以民主党候选人身份参加2000年大选。</p><p>戈尔有多种竞选路线可选。他可以全面拥抱克林顿的政治遗产，无论其利弊。在政治立场上，他可以走中间路线，也可以向左转，比克林顿更接近传统的自由派民主党人。知名的拉尔夫·纳德代表绿党参选，让这一选择更为复杂。戈尔实际上是在两条战线上竞选。</p>',
79: '<p>拉尔夫·纳德从事社会运动和消费者权益倡导多年，如今代表绿党参加2000年大选。</p><p>比尔·克林顿执政八年后，美国显然需要一个真正的自由派选择，为公平贸易、全民医疗、免费大学教育和竞选资金改革而奋斗。纳德此次选举的首要目标是拿到5%的普选票，让绿党有资格在2004年获得联邦配套竞选资金。</p>',
92: '<p>理查德·尼克松辞职后，杰拉尔德·福特于1974年8月9日就任总统。他赦免尼克松的决定极不受欢迎，进一步强化了民众希望由政坛局外人执政的情绪。通货膨胀和失业也拖累了他的支持率。另一方面，福特拥有总统身份带来的威望，并与许多外国领导人谈判过。他在竞选开始时落后，必须一边维持党内团结，一边迅速追回差距。</p>',
105: '<p>约翰·F.·肯尼迪自1953年起担任参议员。他出身富裕的政治家族，年轻且上镜。他过去是温和派参议员，如今必须争取那些原本支持其他候选人的自由派。与此同时，无论他在民权问题上采取何种立场，几乎都会疏远党内的某个重要群体。一种应对策略是巧妙淡化这些分歧，将重点放在冷战上。肯尼迪若当选，将成为首位天主教徒总统。</p>',
106: '<p>理查德·尼克松已经担任副总统八年，竞选开始时，他的知名度高于对手。他长期以坚定的反共主义者和冷战斗士著称。在民权问题上，党内各派的诉求不同，因此他也面临肯尼迪遇到的问题，只是程度较轻。另一方面，尼克松可能比肯尼迪更有条件塑造重视国防、态度强硬的形象。一些选民也认为他冷漠，难以亲近。</p>',
6970: '<p>林登·B.·约翰逊并非经选举成为总统，原本也没打算在1964年竞逐总统。但约翰·F.·肯尼迪去世后，他被推上了美国最高职位，成为众人关注的焦点。迄今为止，他一方面延续肯尼迪的政策，另一方面也推动自己的政治抱负。随着社会保障范围的扩大，以及具有里程碑意义的1964年《民权法案》通过，“伟大社会”计划已经开始推进。在外交方面，约翰逊扩大了美国对越南的介入——这一决定广受欢迎，尽管反对的暗流已经开始涌动。</p><p>约翰逊进入1964年竞选时，几乎拥有一切想要的优势：现任身份、高支持率、强劲势头，以及分裂的对手阵营。几乎人人都预计他会大胜。他只需尽量少犯错误，充分利用戈德华特的极端立场，胜利应该就能轻松到手。</p>',
6969: '作为共和党保守派的领袖，巴里·戈德华特也许是近年来获得总统提名的人物中最具争议的一位。他以坚定的保守主义立场闻名，主张改革社会保障、实行小政府，并停止进一步的民权立法。他深受支持者爱戴，却与共和党内的温和派和自由派互无好感。漫长且争执激烈的初选中，他仅以微弱优势击败纳尔逊·洛克菲勒，又投票反对1964年《民权法案》，损害了自己的政治前景，让这些派别更加不满。</p><p>竞选开始时，戈德华特处境艰难：对手是广受欢迎的现任总统，他自己则背负激进名声，还容易说出严重失言的话。要重新取得竞争力，尚且需要技巧和运气，更不用说获胜了。若想保留入主白宫的希望，他必须尽量少犯错误，争取心存戒备的温和派，并重新团结在他领导下四分五裂的政党。',
116: '<p>富兰克林·罗斯福去世后，哈里·杜鲁门继任总统，带领国家走过第二次世界大战的最后阶段。此后，他的支持率急剧下滑。他对苏联的强硬立场引来了左翼挑战；他在1946年罢工中的做法疏远了工会；他支持民权措施，又促使另一批民主党人另组政党。杜鲁门若想有机会获胜，就必须彻底改变竞选局面。</p>',
117: '<p>纽约州州长托马斯·杜威第二次角逐总统。他因起诉纽约黑手党人物而成名，是共和党东部商界建制派的代表。1944年，他猛烈攻击罗斯福的竞选方式疏远了一些选民。这次，顾问建议他采取更谨慎、更温和的策略，尤其是考虑到他已拥有巨大的领先优势。</p>',
132: '<p>亨利·克莱第三次角逐总统宝座，起初被看好能击败波尔克。他必须尽快明确对得克萨斯问题的立场，但无论怎样表态，都很难不疏远辉格党内的某一派。</p><p>克莱更愿意将奴隶制和领土扩张暂放一边，推动自己重视的关税、国内基础设施建设和全国统一货币等主张。他能否洗刷以往败给安德鲁·杰克逊的失意，终于入主白宫？</p>',
142: '<p>伍德罗·威尔逊在1912年大选中大胜，并在首个任期内推动通过了一系列法律。但到1916年，外交事务逐渐成为焦点。民主党内有一批声势很大、人数却不多的强烈反战者，期待威尔逊同样反战。他能否说服选民，自己推动的反垄断法、童工法、所得税宪法修正案和《联邦储备法》，足以让他获得连任？他最近再婚的消息，也引发了一些闲言碎语。</p>',
143: '<p>查尔斯·埃文斯·休斯曾任纽约州州长，自1910年起担任最高法院大法官，后辞职接受共和党提名。他是各派折中选择的候选人——1912年党内陷入严重分裂时，他正在最高法院任职。休斯很难既批评威尔逊的立法，又不失去罗斯福等进步派的支持。许多共和党人主张对德国采取强硬立场，另一些人则希望他巧妙处理这一问题。</p>',
152: '<p>乔治·布什担任副总统八年，还曾任美国驻联合国大使、共和党全国委员会主席和中央情报局局长。他希望接替广受欢迎的里根，却必须摆脱自己<em>过分</em>依赖这位前上司的印象。他既要证明自己有独立性、坚定的政治理念和担任总统所需的实力，又要设法削弱对手的支持率。竞选开始时，布什似乎远远落后。</p>',
153: '<p>迈克尔·杜卡基斯曾三次当选马萨诸塞州州长。如果能强调自己的能力，并质疑布什是否已准备好当总统，他今年的胜算似乎不错。他赢得提名时，并未明确依附于党内某个派别。他在全国的形象较为正面，却还不够鲜明。人们期待他更清楚地表明自己是谁，而一些早年的投票和决定逐渐受到关注时，他也可能需要加以解释。</p>',
165: '<p>希拉里·克林顿如预期般赢得党内提名，如今面对的却是出人意料的对手——唐纳德·特朗普。她向来被视为主流民主党人，但在初选中明显向左转。她以有利形势进入大选，却将在多个方面遭到持续攻击。她能否让选民相信，自己真正了解美国人民的处境——或者，至少特朗普会是更糟糕的选择？</p>',
166: '<p>唐纳德·特朗普在一场撕裂党内的竞争中赢得共和党提名，震惊了政治建制派。他在移民和减税问题上态度强硬，在许多其他议题上也采取了非传统立场。他必须团结本党，同时设法争取原本可能支持克林顿的选民——或者削弱他们的投票热情，让他们干脆留在家中。他会继续采用初选中行之有效的持续攻击策略吗？</p>',
201: '<p>希拉里·克林顿如预期般赢得党内提名，如今面对的却是出人意料的对手——唐纳德·特朗普。她向来被视为主流民主党人，但在初选中明显向左转。她以有利形势进入大选，却将在多个方面遭到持续攻击。她能否让选民相信，自己真正了解美国人民的处境——或者，至少特朗普会是更糟糕的选择？</p>',
300: '<p>乔·拜登在几乎出局的情况下逆转，赢得民主党提名。竞选开始时，他似乎在民调中略微领先现任总统唐纳德·特朗普。此次竞选的社会情绪比平时更加激烈。拜登能否兑现缓和紧张局势的承诺，还是会被接踵而来的事件吞没？</p>',
301: '<p>唐纳德·特朗普总统带着现任身份的优势进入竞选，却似乎第二次处于不被看好的位置。他能否再次组织起足以获胜的支持联盟？这会是2016年助他跨过终点线的同一批人吗？疫情和“黑人的命也是命”运动，让他的任务更加复杂。</p>',
}
path=BASE/'editorial-records.json'
output=json.loads(path.read_text(encoding='utf-8')) if path.exists() else {}
for pk,zh in translations.items():
    rows=[r for r in cat['records'] if r['scope']=='base' and r['collection']=='candidate_json' and r['location'].get('pk')==pk and r['field']=='description']
    if len(rows)!=1: raise ValueError((pk,len(rows)))
    output[rows[0]['source']]=zh
path.write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Reviewed complete biography fields',len(output))
